/**
 * Get the number of users interested in an event
 * @param eventId The ID of the event
 * @returns The number of users interested in the event
 */
export const getEventInterestCount = async (eventId: string): Promise<number> => {
  try {
    const { count, error } = await supabase
      .from("event_attendees")
      .select("*", { count: "exact", head: true })
      .eq("event_id", eventId);
      
    if (error) {
      console.error("Error getting event interest count:", error);
      return 0;
    }
    
    return count || 0;
  } catch (error) {
    console.error("Error getting event interest count:", error);
    return 0;
  }
};

/**
 * Check if a user is interested in an event
 * @param eventId The ID of the event
 * @param userId The ID of the user
 * @returns Whether the user is interested in the event
 */
export const isUserInterestedInEvent = async (eventId: string, userId: string): Promise<boolean> => {
  try {
    const { data, error } = await supabase
      .from("event_attendees")
      .select("id")
      .eq("event_id", eventId)
      .eq("user_id", userId)
      .maybeSingle();
      
    if (error) {
      console.error("Error checking if user is interested in event:", error);
      return false;
    }
    
    return !!data;
  } catch (error) {
    console.error("Error checking if user is interested in event:", error);
    return false;
  }
};

/**
 * Check a user into an event
 * @param eventId The ID of the event
 * @param userId The ID of the user
 * @returns Whether the check-in was successful
 */
export const checkInUserToEvent = async (eventId: string, userId: string): Promise<boolean> => {
  try {
    // First check if the user is already interested in the event
    const isInterested = await isUserInterestedInEvent(eventId, userId);
    
    if (isInterested) {
      // If already interested, update the check-in time
      const { error } = await supabase
        .from("event_attendees")
        .update({ check_in_time: new Date().toISOString() })
        .eq("event_id", eventId)
        .eq("user_id", userId);
        
      if (error) {
        console.error("Error checking in user to event:", error);
        return false;
      }
    } else {
      // If not interested, add a new record with check-in time
      const { error } = await supabase
        .from("event_attendees")
        .insert({
          event_id: eventId,
          user_id: userId,
          check_in_time: new Date().toISOString()
        });
        
      if (error) {
        console.error("Error checking in user to event:", error);
        return false;
      }
    }
    
    return true;
  } catch (error) {
    console.error("Error checking in user to event:", error);
    return false;
  }
};
